        if (!match) return { cleanText: text2, heading: "", followups: [] };
        const cleanText = text2.replace(/\[followups(?:\s+heading="[^"]*")?\]\s*\n?[\s\S]*?\[\/followups\]/, "").trimEnd();
        const heading = match[1] || "";
