            const matchIndex = m.index ?? 0;
            const source = sources.find((s) => s.num === num2);
            if (!source) continue;
            if (matchIndex > lastIndex) {
              fragment.appendChild(document.createTextNode(text2.slice(lastIndex, matchIndex)));
            }
