// src/ui/settings/skipHints.ts
var STEP_MESSAGES = {
  "llm-model": "You skipped this during setup. Add at least one LLM model so the agent can answer messages.",
  "embedding-model": "You skipped this during setup. Add an embedding model to unlock semantic search and memory retrieval.",
  "search-provider": "You skipped this during setup. Configure a search provider (Tavily, Brave) to enable the agent's web-search tools.",
  "role-models": "You skipped this during setup. Optionally assign smaller, cheaper models to titling, internal calls and memory extraction."
};
function renderSkipHintIfSkipped(containerEl, plugin, stepId) {
  const skipped = plugin.settings.onboarding?.skippedSteps;
  if (!skipped || !skipped.includes(stepId)) return false;
  const message = STEP_MESSAGES[stepId];
  if (!message) return false;
  const banner = containerEl.createDiv({ cls: "vault-operator-skip-hint" });
  banner.style.display = "flex";
  banner.style.alignItems = "flex-start";
  banner.style.gap = "12px";
  banner.style.padding = "10px 12px";
  banner.style.margin = "0 0 12px 0";
  banner.style.borderLeft = "3px solid var(--interactive-accent)";
  banner.style.background = "var(--background-secondary)";
  banner.style.borderRadius = "4px";
  const text2 = banner.createDiv();
  text2.style.flex = "1";
  text2.style.fontSize = "0.9em";
  const headline = text2.createEl("strong");
  headline.setText("Setup left this for later");
  headline.style.display = "block";
  headline.style.marginBottom = "4px";
  text2.createDiv({ text: message });
  const actions = banner.createDiv();
  actions.style.display = "flex";
  actions.style.gap = "6px";
  actions.style.alignItems = "center";
  const reopenBtn = actions.createEl("button", { text: "Reopen wizard" });
  reopenBtn.addEventListener("click", async () => {
    const { FirstRunWizardModal: FirstRunWizardModal2 } = await Promise.resolve().then(() => (init_FirstRunWizardModal(), FirstRunWizardModal_exports));
    new FirstRunWizardModal2(plugin.app, plugin).open();
  });
  const dismissBtn = actions.createEl("button", { text: "Dismiss" });
  dismissBtn.addEventListener("click", async () => {
    const arr = plugin.settings.onboarding.skippedSteps;
    const idx = arr.indexOf(stepId);
    if (idx >= 0) {
      arr.splice(idx, 1);
      await plugin.saveSettings();
    }
    banner.detach();
  });
  return true;
}

