init_safeRegex();
var MAX_RESULTS = 50;
var MAX_FILES_TO_SCAN = 500;
var SearchFilesTool = class extends BaseTool {
  name = "search_files";
  isWriteOperation = false;
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "search_files",
      description: 'Search for a text pattern across files in the vault. Returns matching lines with file path and line numbers. Use path "/" to search the entire vault.',
      input_schema: {
        type: "object",
        properties: {
          path: {
            type: "string",
            description: 'Directory to search in (relative to vault root, or "/" for entire vault)'
          },
          pattern: {
            type: "string",
            description: "Text or regular expression to search for"
          },
          file_pattern: {
            type: "string",
            description: 'Optional file extension filter, e.g. ".md" or ".txt"'
          }
        },
        required: ["path", "pattern"]
      }
    };
  }
  async execute(input, context) {
    const { callbacks } = context;
    const rawPath = input.path ?? "/";
    const pattern = input.pattern ?? "";
    const filePattern = input.file_pattern;
    if (!pattern) {
      callbacks.pushToolResult(this.formatError(new Error("pattern parameter is required")));
      return;
    }
    try {
      const regex = safeRegex(pattern, "i");
      const dirPath = rawPath === "/" || rawPath === "" ? "" : rawPath;
      const ignoreService = this.plugin.ignoreService;
      let files = this.app.vault.getFiles().filter((f3) => {
        if (ignoreService.isIgnored(f3.path)) return false;
        if (dirPath && !f3.path.startsWith(dirPath + "/") && f3.path !== dirPath) return false;
        if (filePattern && !f3.name.endsWith(filePattern)) return false;
        return true;
      });
      if (files.length > MAX_FILES_TO_SCAN) {
        files = files.slice(0, MAX_FILES_TO_SCAN);
      }
      const results = [];
      let totalMatches = 0;
      for (const file of files) {
        if (totalMatches >= MAX_RESULTS) break;
        let content;
        try {
          content = await this.app.vault.cachedRead(file);
        } catch {
          continue;
        }
        const lines = content.split("\n");
        const fileMatches = [];
        for (let i3 = 0; i3 < lines.length; i3++) {
          if (regex.test(lines[i3])) {
            fileMatches.push(`  L${i3 + 1}: ${lines[i3].trim()}`);
            totalMatches++;
            if (totalMatches >= MAX_RESULTS) break;
          }
        }
        if (fileMatches.length > 0) {
          results.push(`${file.path}:
${fileMatches.join("\n")}`);
        }
      }
      if (results.length === 0) {
        callbacks.pushToolResult(`No matches found for "${pattern}" in "${rawPath}".`);
        return;
      }
      const header = `Found ${totalMatches} match(es) for "${pattern}" in "${rawPath || "/"}":${totalMatches >= MAX_RESULTS ? ` (showing first ${MAX_RESULTS})` : ""}

`;
      callbacks.pushToolResult(header + results.join("\n\n"));
      callbacks.log(`Search "${pattern}" found ${totalMatches} matches across ${results.length} files`);
    } catch (error2) {
      callbacks.pushToolResult(this.formatError(error2));
      await callbacks.handleError("search_files", error2);
    }
  }
};

