// src/core/tools/vault/ListPinnedConversationsTool.ts
var ListPinnedConversationsTool = class extends BaseTool {
  name = "list_pinned_conversations";
  isWriteOperation = false;
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "list_pinned_conversations",
      description: 'List all chat conversations the user pinned to memory (via the Star button in History or via mark_for_memory). Read-only. Returns conversation id, title, fact count, and last-update timestamp. Use this for "which chats did I save to memory" questions. Complementary to list_memory_source_notes (which lists vault notes registered as memory-source).',
      input_schema: {
        type: "object",
        properties: {
          limit: {
            type: "integer",
            description: "Optional max number of results (default: 50)."
          }
        }
      }
    };
  }
  // eslint-disable-next-line @typescript-eslint/require-await -- ToolExecution interface contract: async signature shared with tools that do LLM calls
  async execute(input, ctx) {
    const limit2 = typeof input.limit === "number" && input.limit > 0 ? input.limit : 50;
    const memoryDB = this.plugin.memoryDB;
    if (!memoryDB?.isOpen()) {
      ctx.callbacks.pushToolResult(this.formatError("Memory database is not available."));
      return;
    }
    const rows = [];
    try {
      const result = memoryDB.getDB().exec(
        `SELECT source_session_id, COUNT(*) as cnt
                   FROM facts
                  WHERE source_session_id IS NOT NULL
                    AND is_latest = 1
                    AND deprecated_at IS NULL
                  GROUP BY source_session_id
                  ORDER BY cnt DESC
                  LIMIT ?`,
        [limit2]
      );
      if (result.length > 0) {
        for (const v of result[0].values) {
          const id = v[0];
          const cnt = Number(v[1]);
          if (id) rows.push({ sessionId: id, factCount: cnt });
        }
      }
    } catch (e3) {
      console.warn("[list_pinned_conversations] DB query failed:", e3);
      ctx.callbacks.pushToolResult(this.formatError("Failed to query pinned conversations."));
      return;
    }
    if (rows.length === 0) {
      ctx.callbacks.pushToolResult(this.formatSuccess(
        "No conversations pinned to memory yet. Use the Star button in History or call mark_for_memory while a chat is open."
      ));
      return;
    }
    const metas = this.plugin.conversationStore?.list() ?? [];
    const metaById = new Map(metas.map((m) => [m.id, m]));
    const lines = [
      `Pinned conversations (${rows.length}):`,
      ""
    ];
    for (const r3 of rows) {
      const meta = metaById.get(r3.sessionId);
      if (meta) {
        const title = meta.title?.replace(/\n.*/s, "").trim() || "(untitled)";
        const updated = meta.updated ? ` updated=${meta.updated.slice(0, 10)}` : "";
        lines.push(`- ${title} -- id=${r3.sessionId}, ${r3.factCount} facts,${updated}`);
      } else {
        lines.push(`- (deleted conversation) -- id=${r3.sessionId}, ${r3.factCount} facts`);
      }
    }
    ctx.callbacks.pushToolResult(this.formatSuccess(lines.join("\n")));
  }
};

