var CreateBaseTool = class extends BaseTool {
  name = "create_base";
  isWriteOperation = true;
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "create_base",
      description: `Create an Obsidian Bases file (.base) \u2014 a structured view over vault notes. Bases filter and display notes by their frontmatter properties. IMPORTANT: This is Obsidian's native Bases feature, NOT the "DB Folder" plugin. If the user asks for a "DB Folder" table, do NOT use this tool \u2014 use the DB Folder plugin via execute_command("dbfolder:create-new-database-folder") instead. Only use create_base when the user explicitly asks for a Bases view or .base file.`,
      input_schema: {
        type: "object",
        properties: {
          path: {
            type: "string",
            description: 'File path for the base (must end with .base, e.g. "Projects.base")'
          },
          view_name: {
            type: "string",
            description: 'Display name for the first view (e.g. "All Projects")'
          },
          filter_property: {
            type: "string",
            description: 'Frontmatter property to filter on (e.g. "Kategorie", "Status", "tags")'
          },
          filter_values: {
            type: "array",
            items: { type: "string" },
            description: "Values the filter property must match (uses containsAny logic)"
          },
          columns: {
            type: "array",
            items: { type: "string" },
            description: 'Column names to show in the table (e.g. ["file.name", "Status", "Tags"]). file.name is always first.'
          },
          sort_property: {
            type: "string",
            description: "Property to sort by (optional)"
          },
          sort_direction: {
            type: "string",
            enum: ["ASC", "DESC"],
            description: "Sort direction (default: ASC)"
          },
          exclude_templates: {
            type: "boolean",
            description: 'Exclude notes whose name contains "Template" (default: true)'
          }
        },
        required: ["path", "view_name"]
      }
    };
  }
  async execute(input, context) {
    const { callbacks } = context;
    const path12 = (input.path ?? "").trim();
    const viewName = (input.view_name ?? "Table").trim();
    const filterProp = input.filter_property ?? "";
    const filterValues = Array.isArray(input.filter_values) ? input.filter_values : [];
    const columns = Array.isArray(input.columns) ? input.columns : ["file.name"];
    const sortProp = input.sort_property ?? "";
    const sortDir = input.sort_direction ?? "ASC";
    const excludeTemplates = input.exclude_templates !== false;
    if (!path12) {
      callbacks.pushToolResult(this.formatError(new Error("path is required")));
      return;
    }
    if (!path12.endsWith(".base")) {
      callbacks.pushToolResult(this.formatError(new Error("path must end with .base")));
      return;
    }
    try {
      const existingFile = this.app.vault.getFileByPath(path12);
      if (existingFile) {
        callbacks.pushToolResult(
          `<error>Base file already exists: ${path12}. Use update_base to add or modify views in an existing base. Do NOT use create_base on existing files.</error>`
        );
        return;
      }
      const filterConditions = [];
      if (filterProp && filterValues.length > 0) {
        const quotedValues = filterValues.map((v) => `"${v.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`).join(", ");
        filterConditions.push(`${filterProp}.containsAny(${quotedValues})`);
      }
      if (excludeTemplates) {
        filterConditions.push(`'!file.name.contains("Template")'`);
      }
      const lines = ["views:"];
      lines.push(`  - type: table`);
      lines.push(`    name: ${viewName}`);
      if (filterConditions.length > 0) {
        lines.push(`    filters:`);
        lines.push(`      and:`);
        for (const cond of filterConditions) {
          lines.push(`        - ${cond}`);
        }
      }
      const orderedCols = ["file.name", ...columns.filter((c3) => c3 !== "file.name")];
      lines.push(`    order:`);
      for (const col of orderedCols) {
        lines.push(`      - ${col}`);
      }
      if (sortProp) {
        lines.push(`    sort:`);
        lines.push(`      - property: ${sortProp}`);
        lines.push(`        direction: ${sortDir}`);
      }
      lines.push(`    rowHeight: medium`);
      const yaml = lines.join("\n") + "\n";
      const dir = path12.includes("/") ? path12.split("/").slice(0, -1).join("/") : null;
      if (dir) {
        await this.app.vault.createFolder(dir).catch(() => {
        });
      }
      await this.app.vault.create(path12, yaml);
      callbacks.pushToolResult(`Created base: **${path12}**

Open the file in Obsidian to view it as a database table.`);
      callbacks.log(`Created base: ${path12}`);
    } catch (error2) {
      callbacks.pushToolResult(this.formatError(error2));
      await callbacks.handleError("create_base", error2);
    }
  }
};

// src/core/tools/vault/UpdateBaseTool.ts
var UpdateBaseTool = class extends BaseTool {
  name = "update_base";
  isWriteOperation = true;
  constructor(plugin) {
    super(plugin);
  }
  getDefinition() {
    return {
      name: "update_base",
      description: "Add a new view to an existing Obsidian Bases file, or replace a view with a new configuration.",
      input_schema: {
        type: "object",
        properties: {
          path: {
            type: "string",
            description: "Path to the existing .base file"
          },
          view_name: {
            type: "string",
            description: "Name for the new view (if a view with this name exists, it is replaced)"
          },
          filter_property: {
            type: "string",
            description: "Frontmatter property to filter on"
          },
          filter_values: {
            type: "array",
            items: { type: "string" },
            description: "Values the filter property must match"
          },
          columns: {
            type: "array",
            items: { type: "string" },
            description: "Column names to show in the table"
          },
          sort_property: {
            type: "string",
            description: "Property to sort by (optional)"
          },
          sort_direction: {
            type: "string",
            enum: ["ASC", "DESC"],
            description: "Sort direction (default: ASC)"
          },
          exclude_templates: {
            type: "boolean",
            description: 'Exclude notes whose name contains "Template" (default: true)'
          }
        },
        required: ["path", "view_name"]
      }
    };
  }
  async execute(input, context) {
    const { callbacks } = context;
    const path12 = (input.path ?? "").trim();
    const viewName = (input.view_name ?? "").trim();
    const filterProp = input.filter_property ?? "";
    const filterValues = Array.isArray(input.filter_values) ? input.filter_values : [];
    const columns = Array.isArray(input.columns) ? input.columns : ["file.name"];
    const sortProp = input.sort_property ?? "";
    const sortDir = input.sort_direction ?? "ASC";
    const excludeTemplates = input.exclude_templates !== false;
    if (!path12 || !viewName) {
      callbacks.pushToolResult(this.formatError(new Error("path and view_name are required")));
      return;
    }
    try {
      const file = this.app.vault.getFileByPath(path12);
      if (!file) {
        callbacks.pushToolResult(this.formatError(new Error(`Base file not found: ${path12}`)));
        return;
      }
      const existing = await this.app.vault.read(file);
      const filterConditions = [];
      if (filterProp && filterValues.length > 0) {
        const quotedValues = filterValues.map((v) => `"${v.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`).join(", ");
        filterConditions.push(`${filterProp}.containsAny(${quotedValues})`);
      }
      if (excludeTemplates) {
        filterConditions.push(`'!file.name.contains("Template")'`);
      }
      const viewLines = [];
      viewLines.push(`  - type: table`);
      viewLines.push(`    name: ${viewName}`);
      if (filterConditions.length > 0) {
        viewLines.push(`    filters:`);
        viewLines.push(`      and:`);
        for (const cond of filterConditions) {
          viewLines.push(`        - ${cond}`);
        }
      }
      const orderedCols = ["file.name", ...columns.filter((c3) => c3 !== "file.name")];
      viewLines.push(`    order:`);
      for (const col of orderedCols) {
        viewLines.push(`      - ${col}`);
      }
      if (sortProp) {
        viewLines.push(`    sort:`);
        viewLines.push(`      - property: ${sortProp}`);
        viewLines.push(`        direction: ${sortDir}`);
      }
      viewLines.push(`    rowHeight: medium`);
      const newViewBlock = viewLines.join("\n");
      const viewStartRegex = new RegExp(`^  - type: table\\s*\\n    name: ${this.escapeRegex(viewName)}`, "m");
      if (viewStartRegex.test(existing)) {
        const viewBlockRegex = new RegExp(
          `(  - type: table\\s*\\n    name: ${this.escapeRegex(viewName)}[\\s\\S]*?)(?=\\n  - type:|$)`,
          "m"
        );
        const updated = existing.replace(viewBlockRegex, newViewBlock);
        await this.app.vault.modify(file, updated);
        callbacks.pushToolResult(`Updated view "${viewName}" in **${path12}**`);
      } else {
        const updated = existing.trimEnd() + "\n" + newViewBlock + "\n";
        await this.app.vault.modify(file, updated);
        callbacks.pushToolResult(`Added view "${viewName}" to **${path12}**`);
      }
      callbacks.log(`Updated base: ${path12} (view: ${viewName})`);
    } catch (error2) {
      callbacks.pushToolResult(this.formatError(error2));
      await callbacks.handleError("update_base", error2);
    }
  }
  escapeRegex(s) {
    return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
};

