    const path12 = require("path");
    const os4 = require("os");
    const oldRoot = path12.join(os4.homedir(), ".obsidian-agent");
    const newRoot = this.globalFs.getRoot();
    if (oldRoot === newRoot) return;
    try {
      await fs11.promises.access(oldRoot);
    } catch {
      console.debug("[Plugin] No legacy ~/.obsidian-agent/ found \u2014 skip migration");
      await this.cleanupLegacyVaultDirs();
      return;
    }
    console.debug(`[Plugin] Migrating storage: ${oldRoot} -> ${newRoot}`);
    await fs11.promises.mkdir(newRoot, { recursive: true });
    const dirsToMigrate = ["memory", "history", "logs", "rules", "skills", "workflows"];
    let migrated = 0;
    for (const dir of dirsToMigrate) {
      const src = path12.join(oldRoot, dir);
      const dst = path12.join(newRoot, dir);
      try {
        await fs11.promises.access(src);
        try {
          await fs11.promises.access(dst);
        } catch {
          await fs11.promises.cp(src, dst, { recursive: true });
          migrated++;
        }
      } catch {
      }
    }
    const filesToMigrate = ["settings.json", "pending-extractions.json"];
    for (const file of filesToMigrate) {
      const src = path12.join(oldRoot, file);
      const dst = path12.join(newRoot, file);
      try {
        await fs11.promises.access(src);
        try {
          await fs11.promises.access(dst);
        } catch {
          await fs11.promises.copyFile(src, dst);
          migrated++;
        }
      } catch {
      }
    }
