    const newKnowledgeDb = path12.join(vaultBasePath, ".obsilo-vault", "knowledge.db");
    try {
      await fs11.promises.access(oldKnowledgeDb);
      await fs11.promises.mkdir(path12.dirname(newKnowledgeDb), { recursive: true });
      try {
        await fs11.promises.access(newKnowledgeDb);
      } catch {
        await fs11.promises.copyFile(oldKnowledgeDb, newKnowledgeDb);
        migrated++;
        console.debug("[Plugin] Migrated knowledge.db to vault-local");
      }
    } catch {
    }
    const oldMemoryDb = path12.join(vaultBasePath, ".obsidian-agent", "memory.db");
    const newMemoryDb = path12.join(newRoot, "memory.db");
    try {
      await fs11.promises.access(oldMemoryDb);
      try {
        await fs11.promises.access(newMemoryDb);
      } catch {
        await fs11.promises.copyFile(oldMemoryDb, newMemoryDb);
        migrated++;
        console.debug("[Plugin] Migrated memory.db to vault-parent");
      }
    } catch {
    }
    console.debug(`[Plugin] Storage migration complete: ${migrated} items migrated`);
    await this.cleanupLegacyVaultDirs();
